<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter} from 'vue-router';
import {ArrowLeft,ArrowUpRight,Check,CheckCircle2,Copy,Download,FileArchive,GitBranch,History,LoaderCircle,Package,Plus,RefreshCw,Search,Share2,ShieldCheck,Star,Trash2,X} from 'lucide-vue-next';
import type {DatasetRelease,ReleaseList,ReleaseShare} from '../../../../packages/shared/src/releases';
import {patch,post,remove,request} from '../api';
import {useAppStore} from '../stores/app';
import ReleaseMarkdown from './SafeMarkdown.vue';
const props=defineProps<{base:string;branch:string;canManage?:boolean;canShare?:boolean;canExport?:boolean}>();
const emit=defineEmits<{'open-version':[commitId:string]}>();
const app=useAppStore(),route=useRoute(),router=useRouter();
const items=ref<DatasetRelease[]>([]),capabilities=ref({manage:false,share:false,export:false}),loading=ref(false),busy=ref(false),error=ref(''),search=ref(''),filter=ref('all'),kind=ref<'releases'|'snapshots'>(route.query.releaseKind==='snapshots'?'snapshots':'releases');
const selectedId=ref(typeof route.query.release==='string'?route.query.release:''),selected=computed(()=>items.value.find(item=>item.id===selectedId.value));
const visible=computed(()=>items.value.filter(item=>(filter.value==='all'||filter.value==='stable'&&!item.prerelease&&item.status==='published'||filter.value==='prerelease'&&item.prerelease||filter.value==='drafts'&&['draft','queued','building','ready','failed'].includes(item.status))&&(item.version+' '+item.title).toLowerCase().includes(search.value.toLowerCase())));
const formBaseline=ref(''),includeArchives=ref(false),snapshotArchives=ref(false);
const creating=ref(false),editingId=ref(''),version=ref(''),title=ref(''),notes=ref(''),sourceRef=ref(props.branch),prerelease=ref(false),dialog=ref<HTMLElement>(),formError=ref('');
const errataOpen=ref(false),errataDraft=ref('');
const shares=ref<ReleaseShare[]>([]),shareDays=ref('7'),shareLink=ref(''),showSharing=ref(false),showAudit=ref(false);
let generation=0,poll:ReturnType<typeof setTimeout>|undefined,disposed=false,previousFocus:HTMLElement|null=null;
const label=(status:string,itemKind:DatasetRelease['kind']='release')=>itemKind==='snapshot'&&status==='ready'?'可下载':({draft:'草稿',queued:'排队中',building:'构建中',ready:'待发布核对',published:'已发布',failed:'构建失败',withdrawn:'已撤回'}[status]??status);
const timestamp=(value?:string)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—';
const bytes=(value:number)=>value<1024?value+' B':value<1024*1024?(value/1024).toFixed(1)+' KiB':(value/1024/1024).toFixed(1)+' MiB';
const localLink=computed(()=>{try{return ['127.0.0.1','localhost','::1','[::1]'].includes(new URL(shareLink.value).hostname);}catch{return false;}});
const formValue=()=>JSON.stringify([version.value,title.value,notes.value,sourceRef.value,prerelease.value,includeArchives.value]);
const releaseFormDirty=computed(()=>creating.value&&formValue()!==formBaseline.value),formDirty=computed(()=>releaseFormDirty.value||!!errataDraft.value.trim());
async function load(quiet=false){const current=++generation;if(!quiet)loading.value=true;error.value='';clearTimeout(poll);try{const result=await request<ReleaseList>(props.base+'/'+kind.value);if(disposed||current!==generation)return;items.value=result.items;capabilities.value=result.capabilities;if(selectedId.value&&!result.items.some(item=>item.id===selectedId.value))selectedId.value='';if(result.items.some(item=>['queued','building'].includes(item.status)))poll=setTimeout(()=>void load(true),1500);}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function choose(item:DatasetRelease){if(!(await discardErratum()))return;selectedId.value=item.id;showSharing.value=false;showAudit.value=false;shares.value=[];shareLink.value='';void router.replace({query:{...route.query,release:item.id,releaseKind:kind.value}});}
function openPrevious(){const item=items.value.find(item=>item.id===selected.value?.comparison?.baseReleaseId);if(item)choose(item);}
async function discardErratum(){if(errataDraft.value.trim()&&!(await app.confirmAction('当前勘误尚未保存，确认放弃并切换吗？',{title:'未保存的勘误',confirmLabel:'放弃并切换'})))return false;errataDraft.value='';errataOpen.value=false;return true;}
async function switchKind(value:'releases'|'snapshots'){if(value===kind.value||!(await discardErratum()))return;kind.value=value;void router.replace({query:{...route.query,release:undefined,releaseKind:value}});}
async function backList(){if(!(await discardErratum()))return;selectedId.value='';void router.replace({query:{...route.query,release:undefined}});}
async function saveErratum(){if(!selected.value||!errataDraft.value.trim()||busy.value)return;busy.value=true;try{await post(props.base+'/releases/'+selected.value.id+'/errata',{expectedRevision:selected.value.revision,body:errataDraft.value});errataDraft.value='';errataOpen.value=false;await load(true);app.notify('勘误已追加，原资产保持原样。');}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function run(action:string,item:DatasetRelease){if(busy.value)return;if(action==='publish'&&!(await app.confirmAction(`发布 ${item.version}？固定提交 ${item.commitId.slice(0,12)}，${item.rowCount??0} 条样本；发布后不能替换资产。`,{title:'发布此版本',confirmLabel:'正式发布'})))return;if(action==='withdraw'&&!(await app.confirmAction(`撤回 ${item.version} 后，该 Release 的资产下载与分享将关闭；有项目导出权限的人仍可导出工作快照。`,{title:'撤回 Release',confirmLabel:'撤回版本'})))return;busy.value=true;error.value='';try{await post(props.base+'/'+(item.kind==='snapshot'?'snapshots':'releases')+'/'+item.id+'/'+action,{expectedRevision:item.revision});await load(true);app.notify(action==='build'?'构建已排队':action==='publish'?'版本已发布':action==='withdraw'?'该 Release 已撤回':'最新稳定版已更新');}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function newSnapshot(){if(busy.value||!capabilities.value.export||!(await discardErratum()))return;busy.value=true;error.value='';try{const item=await post<DatasetRelease>(props.base+'/snapshots',{ref:props.branch,includeArchives:snapshotArchives.value});kind.value='snapshots';await load(true);await choose(item);app.notify('工作快照已排队；不包含未保存草稿，也不代表完成复核。');}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function openCreate(item?:DatasetRelease){if(!(await discardErratum()))return;previousFocus=document.activeElement as HTMLElement;editingId.value=item?.id??'';version.value=item?.version??'';title.value=item?.title??'';notes.value=item?.notes??'';sourceRef.value=item?.sourceRef??props.branch;prerelease.value=item?.prerelease??false;includeArchives.value=item?.includeArchives??false;formError.value='';formBaseline.value=formValue();creating.value=true;await nextTick();dialog.value?.querySelector<HTMLInputElement>('input')?.focus();}
async function closeCreate(){if(busy.value)return;if(releaseFormDirty.value&&!(await app.confirmAction('当前版本表单尚未保存，确认关闭吗？',{title:'未保存的发布草稿',confirmLabel:'放弃表单'})))return;creating.value=false;previousFocus?.focus();}
function trap(event:KeyboardEvent){if(event.key!=='Tab')return;const controls=dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled)');if(!controls?.length)return;const first=controls[0]!,last=controls[controls.length-1]!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
async function save(){if(busy.value)return;busy.value=true;formError.value='';try{const input={version:version.value.trim(),title:title.value.trim(),notes:notes.value,sourceRef:sourceRef.value.trim(),prerelease:prerelease.value,includeArchives:includeArchives.value};let item:DatasetRelease;if(editingId.value){const current=items.value.find(item=>item.id===editingId.value);if(!current)throw new Error('发布草稿已变化，请刷新。');item=await patch(props.base+'/releases/'+current.id,{...input,expectedRevision:current.revision});}else item=await post(props.base+'/releases',{...input,version:version.value.trim()});creating.value=false;kind.value='releases';await load(true);choose(item);previousFocus?.focus();}catch(cause){formError.value=(cause as Error).message;}finally{busy.value=false;}}
async function loadShares(){if(!selected.value)return;showSharing.value=!showSharing.value;if(!showSharing.value)return;try{shares.value=await request(props.base+'/releases/'+selected.value.id+'/shares');}catch(cause){error.value=(cause as Error).message;}}
async function createShare(){if(!selected.value||busy.value)return;busy.value=true;error.value='';shareLink.value='';try{const result=await post<ReleaseShare&{downloadPath:string}>(props.base+'/releases/'+selected.value.id+'/shares',{expiresAt:new Date(Date.now()+Number(shareDays.value)*86400_000).toISOString()});shareLink.value=window.location.origin+result.downloadPath;shares.value=await request(props.base+'/releases/'+selected.value.id+'/shares');await load(true);}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function revoke(share:ReleaseShare){if(!selected.value||busy.value)return;if(!(await app.confirmAction('撤销此下载链接？已下载的副本不会被收回。',{title:'撤销分享链接',confirmLabel:'撤销链接'})))return;busy.value=true;try{await remove(props.base+'/releases/'+selected.value.id+'/shares/'+share.id);shares.value=await request(props.base+'/releases/'+selected.value.id+'/shares');shareLink.value='';await load(true);}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function copyLink(){try{await navigator.clipboard.writeText(shareLink.value);app.notify('分享链接已复制');}catch{app.notify('请选中链接文本手动复制。');}}
watch(()=>[route.query.release,route.query.releaseKind],()=>{const id=typeof route.query.release==='string'?route.query.release:'';if(id!==selectedId.value){errataDraft.value='';errataOpen.value=false;}selectedId.value=id;kind.value=route.query.releaseKind==='snapshots'?'snapshots':'releases';});
watch(()=>[props.base,kind.value],(value,previous)=>{if(previous&&value[0]!==previous[0]){errataDraft.value='';errataOpen.value=false;creating.value=false;}selectedId.value=route.query.releaseKind===kind.value&&typeof route.query.release==='string'?route.query.release:'';showSharing.value=false;shareLink.value='';void load();});
const allowLeave=async()=>!formDirty.value||await app.confirmAction('当前发布表单或勘误尚未保存，确认离开吗？',{title:'未保存的发布草稿',confirmLabel:'放弃并离开'});onBeforeRouteLeave(allowLeave);onBeforeRouteUpdate((to,from)=>(['namespace','repo','tab'].some(key=>to.params[key]!==from.params[key])||to.query.release!==from.query.release||to.query.releaseKind!==from.query.releaseKind)?allowLeave():true);
function beforeUnload(event:BeforeUnloadEvent){if(formDirty.value){event.preventDefault();event.returnValue='';}}
onMounted(()=>{void load();window.addEventListener('beforeunload',beforeUnload);});onBeforeUnmount(()=>{disposed=true;++generation;clearTimeout(poll);window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template>
<section class="releases-page"><header class="release-page-heading"><div><span class="release-eyebrow"><Package :size="15"/>项目版本与交付</span><h2>Releases</h2><p>将已提交的数据、规范、标注与附件封装为固定版本。</p></div><div><button v-if="capabilities.export" class="btn" :disabled="busy" @click="newSnapshot"><Download :size="15"/>导出工作快照</button><button v-if="capabilities.manage" class="btn btn-primary" @click="openCreate()"><Plus :size="16"/>创建 Release</button></div></header>
<label v-if="capabilities.export" class="release-export-option"><input v-model="snapshotArchives" type="checkbox"/>工作快照附带原始归档（可选；完整 ZIP 超过 64 MiB 时停止，不截断）</label><div class="release-view-tabs"><button :class="{active:kind==='releases'}" @click="switchKind('releases')">项目 Releases <span v-if="kind==='releases'">{{items.length}}</span></button><button v-if="capabilities.export" :class="{active:kind==='snapshots'}" @click="switchKind('snapshots')">我的工作快照</button><button class="btn btn-ghost release-refresh" aria-label="刷新发布列表" :disabled="loading" @click="load()"><RefreshCw :size="14"/></button></div>
<p v-if="kind==='snapshots'" class="release-work-note"><ShieldCheck :size="16"/>工作快照允许导出未完成审核的数据，固定于已提交版本；不包含未保存草稿，不提供正式发布背书。</p>
<div v-if="error" class="error-state" role="alert">{{error}}</div><div v-if="loading" class="empty" role="status"><LoaderCircle class="spin" :size="26"/>正在读取版本…</div>
<template v-else><div v-if="!selected" class="release-list-area"><div class="release-search"><label class="search-field"><Search :size="15"/><input v-model="search" placeholder="搜索版本号或标题…" aria-label="搜索发布版本"/></label><select v-if="kind==='releases'" v-model="filter" aria-label="筛选发布状态"><option value="all">所有版本</option><option value="stable">已发布正式版</option><option value="prerelease">预发布</option><option v-if="capabilities.manage" value="drafts">未发布候选</option></select></div>
<div v-if="!visible.length" class="panel release-empty"><Package :size="38"/><h3>{{items.length?'没有匹配的版本':kind==='snapshots'?'尚未创建工作快照':'尚未发布项目版本'}}</h3><p>{{kind==='snapshots'?'选择已提交的分支导出完整包，继续保留审核状态。':'创建固定提交的候选，通过构建与核对后正式发布。'}}</p><button v-if="capabilities.manage&&kind==='releases'" class="btn btn-primary" @click="openCreate()"><Plus :size="15"/>创建第一个 Release</button></div>
<button v-for="item in visible" :key="item.id" class="release-list-item" @click="choose(item)"><div class="release-marker"><Package :size="21"/></div><div class="release-item-main"><div><strong>{{item.title}}</strong><span v-if="item.latest" class="release-chip latest">最新稳定版</span><span v-if="item.prerelease" class="release-chip">预发布</span><span class="release-status" :class="item.status">{{label(item.status,item.kind)}}</span></div><p><code>{{item.version}}</code><span>{{item.createdBy.name}} · {{timestamp(item.publishedAt??item.createdAt)}}</span></p><p class="release-list-notes">{{item.notes||'未填写版本说明'}}</p><footer><GitBranch :size="12"/><code>{{item.commitId.slice(0,12)}}</code><span v-if="item.rowCount!==undefined">{{item.rowCount.toLocaleString()}} 条样本</span><span>{{item.assets.length}} 项资产</span></footer></div><ArrowUpRight :size="18" class="muted"/></button></div>
<article v-else class="release-detail"><button class="release-back" @click="backList"><ArrowLeft :size="15"/>返回版本列表</button><header class="release-detail-heading"><div><div class="release-detail-badges"><code>{{selected.version}}</code><span class="release-status" :class="selected.status">{{label(selected.status,selected.kind)}}</span><span v-if="selected.latest" class="release-chip latest">最新稳定版</span><span v-if="selected.prerelease" class="release-chip">预发布</span></div><h2>{{selected.title}}</h2><p>{{selected.createdBy.name}} · 创建于 {{timestamp(selected.createdAt)}}<span v-if="selected.publishedAt"> · 发布于 {{timestamp(selected.publishedAt)}}</span></p></div><div class="release-detail-actions"><button v-if="capabilities.manage&&selected.kind==='release'&&['draft','failed','ready'].includes(selected.status)" class="btn" :disabled="busy" @click="openCreate(selected)">编辑草稿</button><button v-if="((selected.kind==='release'&&capabilities.manage)||(selected.kind==='snapshot'&&capabilities.export))&&['draft','failed','ready'].includes(selected.status)" :class="selected.status==='ready'?'btn':'btn btn-primary'" :disabled="busy" @click="run('build',selected)"><LoaderCircle v-if="busy" class="spin" :size="15"/><Package v-else :size="15"/>{{selected.status==='ready'?'重新校验构建':'校验并构建'}}</button><button v-if="capabilities.manage&&selected.kind==='release'&&selected.status==='ready'" class="btn btn-primary" :disabled="busy" @click="run('publish',selected)"><CheckCircle2 :size="15"/>核对并发布</button><button v-if="capabilities.manage&&selected.status==='published'&&!selected.prerelease&&!selected.latest" class="btn" :disabled="busy" @click="run('latest',selected)"><Star :size="14"/>设为最新稳定版</button><button v-if="capabilities.manage&&selected.status==='published'" class="btn btn-ghost" :disabled="busy" @click="run('withdraw',selected)">撤回</button></div></header>
<div class="release-content-grid"><div class="release-body"><div v-if="selected.kind==='snapshot'" class="notice">未发布工作快照 · 原意见及审核证据保留，不能视为已采纳或完成复核。</div><div v-if="['queued','building'].includes(selected.status)" class="release-build-state" role="status"><LoaderCircle class="spin" :size="22"/><div><strong>{{label(selected.status,selected.kind)}}</strong><p>候选固定为 {{selected.commitId.slice(0,12)}}；{{selected.kind==='snapshot'?'完成后可直接下载，保留未审核状态。':'完成后仍需显式核对并发布。'}}</p></div></div><div v-if="selected.error" class="error-state" role="alert"><strong>{{selected.error}}</strong><ul v-if="selected.issues.length"><li v-for="issue in selected.issues" :key="issue">{{issue}}</li></ul></div><div v-if="selected.status==='withdrawn'" class="notice">此 Release 已撤回，资产下载和分享已关闭；历史记录保留。</div><section class="panel release-notes"><header><h3>版本说明</h3><span>受限 Markdown · 不渲染 HTML 或外部资源</span></header><ReleaseMarkdown :source="selected.notes"/><section v-if="selected.errata?.length" class="release-errata"><h4>发布后勘误</h4><article v-for="entry in selected.errata" :key="entry.id"><p>{{entry.actor.name}} · {{timestamp(entry.createdAt)}}</p><ReleaseMarkdown :source="entry.body"/></article></section><div v-if="capabilities.manage&amp;&amp;selected.kind==='release'&amp;&amp;['published','withdrawn'].includes(selected.status)" class="release-erratum-editor"><button class="btn btn-ghost" :disabled="busy" @click="errataOpen=!errataOpen">{{errataOpen?'收起':'添加发布后勘误'}}</button><form v-if="errataOpen" @submit.prevent="saveErratum"><label class="field">补充说明<textarea v-model="errataDraft" rows="4" maxlength="10000" :disabled="busy" placeholder="仅追加勘误；原版本说明与下载资产保持原样。"/></label><button class="btn" :disabled="busy||!errataDraft.trim()">追加勘误并留痕</button></form></div></section>
<section v-if="selected.comparison" class="panel release-comparison"><header><h3>相较 {{selected.comparison.baseVersion}}</h3><button class="btn btn-ghost" @click="openPrevious">查看上版详情</button></header><p v-if="selected.comparison.error" class="notice">上版差异摘要未完成：{{selected.comparison.error}}</p><template v-else><div><span>样本新增 <strong>{{selected.comparison.samples.added}}</strong></span><span>样本删除 <strong>{{selected.comparison.samples.removed}}</strong></span><span>正文修改 <strong>{{selected.comparison.samples.modified}}</strong></span><span>行标签变更 <strong>{{selected.comparison.labelsChanged}}</strong></span><span>附件新增/删除/修改 <strong>{{selected.comparison.attachments.added}} / {{selected.comparison.attachments.removed}} / {{selected.comparison.attachments.modified}}</strong></span></div><p>规范：{{selected.comparison.schemaChanged?'已变化':'未变化'}} · README：{{selected.comparison.readmeChanged?'已变化':'未变化'}} · 数据集/文件标签：{{selected.comparison.scopeLabelsChanged?'已变化':'未变化'}} · 片段/步骤：{{selected.comparison.fragmentsChanged?'已变化':'未变化'}}</p></template></section><section class="panel release-assets"><header><h3><FileArchive :size="17"/>Assets <span>{{selected.assets.length}}</span></h3><span>完整文件与校验值</span></header><div v-if="!selected.assets.length" class="empty">{{selected.status==='failed'?'构建失败，未提供可下载资产。':'完成构建后显示下载资产。'}}</div><div v-for="asset in selected.assets" :key="asset.id" class="release-asset"><FileArchive :size="18"/><div><a v-if="selected.status!=='withdrawn'" :href="'/api'+base+'/'+kind+'/'+selected.id+'/assets/'+asset.id" download>{{asset.name}}<Download :size="14"/></a><strong v-else>{{asset.name}}</strong><code>SHA-256 {{asset.sha256}}</code></div><span>{{bytes(asset.size)}}</span></div></section>
<section v-if="capabilities.share&&selected.kind==='release'&&selected.status==='published'" class="panel release-share"><header><h3><Share2 :size="16"/>固定版本分享</h3><button class="btn btn-ghost" @click="loadShares">{{showSharing?'收起':'管理分享链接'}}</button></header><div v-if="showSharing"><p>链接仅授予本版本完整 ZIP 下载，支持撤销与到期。不会改变仓库可见性或暴露本机网络。</p><div class="share-create"><label>有效期<select v-model="shareDays"><option value="1">1 天</option><option value="7">7 天</option><option value="30">30 天</option></select></label><button class="btn" :disabled="busy" @click="createShare"><Plus :size="14"/>创建下载链接</button></div><div v-if="shareLink" class="created-share"><input :value="shareLink" readonly aria-label="刚创建的分享链接" @focus="($event.target as HTMLInputElement).select()"/><button class="btn" @click="copyLink"><Copy :size="14"/>复制</button><p v-if="localLink">当前地址仅供本机访问。组织外下载需要实际可达的部署地址；本应用不会自动开放网络。</p><p>令牌仅在创建后显示一次，请妥善保存；不要放入公开日志或知识库。</p></div><div v-for="share in shares" :key="share.id" class="share-row"><div><strong>{{share.revokedAt?'已撤销':Date.parse(share.expiresAt)<=Date.now()?'已过期':'有效'}}</strong><span>{{share.createdBy.name}} · 到期 {{timestamp(share.expiresAt)}}</span></div><button v-if="!share.revokedAt&&Date.parse(share.expiresAt)>Date.now()" class="btn btn-ghost" :disabled="busy" @click="revoke(share)"><Trash2 :size="14"/>撤销</button></div></div></section></div>
<aside class="panel release-facts"><h3>版本信息</h3><dl><dt>固定提交</dt><dd><code>{{selected.commitId}}</code><button class="btn btn-ghost" @click="emit('open-version',selected.commitId)">查看只读数据<ArrowUpRight :size="13"/></button></dd><dt>来源分支/版本</dt><dd>{{selected.sourceRef}}</dd><dt>样本</dt><dd>{{selected.rowCount?.toLocaleString()??'待构建'}}</dd><dt>附件</dt><dd>{{selected.attachmentCount??'待构建'}}</dd><dt>构建时间</dt><dd>{{timestamp(selected.builtAt)}}</dd><dt>记录版本</dt><dd>{{selected.revision}}</dd></dl><p>Release 关联 Oxen commit；不会自动创建原生 tag。已发布资产不可替换。</p><button class="btn btn-ghost" @click="showAudit=!showAudit"><History :size="14"/>{{showAudit?'收起':'查看'}}审计记录</button><ol v-if="showAudit" class="release-audit"><li v-for="(entry,index) in selected.audit" :key="index"><strong>{{entry.action}}</strong><span>{{entry.actor.name}} · {{timestamp(entry.at)}}</span></li></ol></aside></div></article></template>
<div v-if="creating" class="modal-backdrop release-dialog-backdrop" @click.self="closeCreate" @keydown.esc.stop.prevent="closeCreate"><section ref="dialog" class="release-dialog" role="dialog" aria-modal="true" aria-labelledby="release-dialog-title" @keydown="trap"><header><div><span class="release-eyebrow">版本候选</span><h2 id="release-dialog-title">{{editingId?'编辑发布草稿':'创建 Release'}}</h2><p>保存草稿后校验构建，再核对资产并显式发布。</p></div><button class="icon-button" :disabled="busy" aria-label="关闭发布表单" @click="closeCreate"><X :size="19"/></button></header><form @submit.prevent="save"><fieldset :disabled="busy"><div class="release-form-grid"><label class="field">版本号<input v-model="version" required pattern="[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}" maxlength="80" placeholder="v1.0.0"/></label><label class="field">来源分支或提交<input v-model="sourceRef" required maxlength="160" placeholder="main"/></label></div><label class="field">标题<input v-model="title" required maxlength="240" placeholder="例如：提示词注入评测集 v1.0"/></label><label class="field">版本说明<textarea v-model="notes" rows="8" maxlength="30000" placeholder="支持标题、列表与代码块；不渲染 HTML。说明本版变更、用途和限制。"/></label><label class="prerelease-choice"><input v-model="prerelease" type="checkbox"/><span><strong>标记为预发布</strong><small>仍需完整校验和独立复核；不会成为最新稳定版。</small></span></label><label class="prerelease-choice"><input v-model="includeArchives" type="checkbox"/><span><strong>附带原始归档（可选）</strong><small>默认仅包含来源清单。原始归档可能包含未选入当前样本的数据；请核对分享范围，完整 ZIP 仍限制 64 MiB。</small></span></label><p class="release-form-note">来源必须是主分支可核对的已合并提交；固定后不会随分支自动前进。未提交的工作与未保存草稿不包含在内。完整 ZIP 上限 64 MiB，超限停止构建，不截断内容。</p></fieldset><div v-if="formError" class="error-state" role="alert">{{formError}}</div><footer><button type="button" class="btn" :disabled="busy" @click="closeCreate">取消</button><button class="btn btn-primary" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="15"/><Check v-else :size="15"/>保存草稿</button></footer></form></section></div>
</section>
</template>
<style scoped src="./releases.css"></style>
